  ('5aa0f733-a4dd-4620-b198-fe7437c2b3ea', 'ASCIUGATUTTO MEGA BLUE 500 - CONFEZIONI DA 2 ROTOLI PER ALIMENTI', 'SETTORE APPLICATIVO: WORKPLACE BRAND: CLASSEUR PROFESSIONAL AMBIENTE: FAI DA TE, INDUSTRIA MATERIA PRIMA: CELLULOSA BLU N° VELI: 3 GRAMMATURA: 17,5 COLORE: BLU LAVORAZIONI PARTICOLARI: GOFFRATO, INCOLLATO, PERFORATO TIPO GOFFRATURA: MICRO IDONEO AL CONTATTO CON ALIMENTI: SI LARGHEZZA FORMATO: 220 MM LUNGHEZZA FORMATO: 340 MM N° STRAPPI: 500 LUNGHEZZA ROTOLO: 170 M DIAMETRO ROTOLO: 290 MM DIAMETRO INTERNO ANIMA: 61 TIPO ANIMA: SFARE', '9b98ba2f-3efe-4085-9247-67487c5d8325', '21ea40d5-5c38-4332-a86c-10390ac3da6e', '23.70', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/ewkq52qh1tv.png', 'true', '1'),
