  ('d38535ef-1437-4dc8-9cae-d5572f8c887e', 'GUANTI NITRILE PALMPRO 667 BLUE 100 PZ VARIE MISURE', '', '9e391273-29b8-4375-ae53-a2603df3d379', '65147988-8a1e-4447-91bc-22a62d2fb608', '5.60', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/ju4mex4tp5e.jpg', 'true', '1'),
  ('d3a9791a-15fe-431e-afd3-0309305a1db4', 'DETERGENTE PER LA RIMOZIONE DI INCROSTAZIONI E RESIDUI CARBONIZZATI 600ML. ADHOC', 'Detergente fortemente alcalino in grado di rimuovere efficacemente residui organici quali grassi animali e vegetali anche carbonizzati ideale per la pulizia di forni, cappe industriali, friggitrici, braccetti macchine da caffè, piastre di cottura e ovunque si debbano rimuovere sporchi e grassi tenaci. MODALITÀ D''IMPIEGO: il prodotto va applicato omogeneamente sulle superfici da trattare con l''apposito vaporizzatore . A freddo va lasciato agire almeno 15-20 minuti. A 40-60 °c il prodotto agisce più velocemente ed i tempi di contatto possono essere ridotti . Il prodotto può essere utilizzato anche diluito in acqua dal 20% al 50% .Si raccomanda di adottare le opportune precauzioni di protezione individuale durante l''uso ,quali occhiali e guanti protettivi.', '9e391273-29b8-4375-ae53-a2603df3d379', '553430c1-2680-4be8-8e1c-83df18c07113', '6.80', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/vf8jrl2wtmg.jpg', 'true', '1'),
  ('d412f3eb-a313-40d5-bfa2-2b414d6f7c7a', 'ROTOLO CARTA SEALING - H 100 METRI 22 - GR. 90', '', '4c48251c-2ba8-4822-8595-a56d401085b0', '19ae6e60-0d77-4df5-9110-64dbbfa40b65', '23.20', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/0u04yi666ypq.jpg', 'true', '1'),
  ('d41d2699-4a4e-408a-acc3-501f80eda558', 'CLOR SAN', 'Sgrassatore sanitizzante ad azione clorexidina. Pulisce ed elimina grassi da tutte le superfici, fornelli, cappe, piani di lavoro, affettatrici e banchi.', '9e391273-29b8-4375-ae53-a2603df3d379', '587bc2b1-09bd-4b0e-82e0-0c7709443115', '4.70', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/q5yrgzze4kg.jpg', 'true', '1'),
