  ('fdbc4f37-1921-4289-b73c-b4c9d5effce9', 'DISINCROSTANTE PER LAVASTOVIGLIE E AMMOLLO HACCP - 5 LT (GENERAL)', 'Disincrostante acido ideale per la rimozione delle incrostazioni in lavastoviglie e lavatrici. Rimuove molto velocemente tutti i residui calcarei. Indicato anche per ambienti HACCP. DILUIZIONE Puro o 20% (2 L in 10 L d’acqua). MODALITÁ D''USO USO MECCANICO: diluire il prodotto direttamente nella vasca della macchina ed effettuare un ciclo di lavaggio. USO MANUALE: lasciare in ammollo i componenti da disincrostare. Lasciare agire e risciacquare. AVVERTENZE Può essere corrosivo per i metalli. Nocivo se ingerito. Provoca gravi ustioni cutanee e gravi lesioni oculari. Lavare accuratamente le mani dopo l’uso. Proteggere gli occhi. IN CASO DI INGESTIONE: sciacquare la bocca. NON provocare il vomito. IN CASO DI CONTATTO CON LA PELLE (o con i capelli): togliersi di dosso immediatamente tutti gli indumenti contaminati. Sciacquare la pelle o fare una doccia. IN CASO DI CONTATTO CON GLI OCCHI: sciacquare accuratamente per parecchi minuti. Togliere le eventuali lenti a contatto se è agevole farlo. Continuare a sciacquare. Contattare immediatamente un CENTRO ANTIVELENI o un medico. Assorbire la fuoriuscita per evitare danni materiali. Contiene ACIDO FOSFORICO.', '9e391273-29b8-4375-ae53-a2603df3d379', '553430c1-2680-4be8-8e1c-83df18c07113', '30.50', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/pec8wzrn83g.png', 'true', '1'),
  ('fdf91c08-4040-473c-8dbd-385f2768793d', 'VASCHETTA FRITTI AVANA INTERNO BIANCO - MISURE CM 16,8x9,5H4,8 CM 500 ML -100 PZ. - 10 CONFEZIONI IN UN CARTONE', 'Vaschetta fritti, KRAFT/PE avana/bianco cm 18x12x4 h 500ml - 100pcs Carta kraft 250 gsm + 15 PE Adatto al contatto con alimenti caldi (70°C per 2 ore), freddi, solidi e liquidi. Non adatto all''utilizzo unitamente con l''alimento nel forno tradizionale e forno a microonde.', '4c48251c-2ba8-4822-8595-a56d401085b0', '47d9516e-721f-47ea-af6a-c8550775743c', '18.10', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/5rs70ggyhuc.jpg', 'true', '1'),
  ('fe1015bf-c8ec-4dd6-a0a6-426789f0da61', 'CARTA VELINA METAL ARGENTO - 50x70 - CONFEZIONE A 25 FOGLI.', '', '4c48251c-2ba8-4822-8595-a56d401085b0', '19ae6e60-0d77-4df5-9110-64dbbfa40b65', '10.35', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/otstdqgsfcp.jpg', 'true', '1'),
  ('fe66e6c3-5085-4ff2-a496-fb9d455b7a9e', 'BOBINA INDUSTRIALE E-TISSUE SAND CARTA ECOLOGICA 500 STRAPPI', 'E-Tissue, la gamma di prodotti in carta ecologica dagli alti standard di performance. Una carta autenticamente ecologica prodotta senza l’uso di additivi chimici, sbiancanti ottici, e senza scarti di lavorazione. E-Tissue è dermatologicamente testata, sicura sulla pelle e certificata ECOLABEL e PEFC. La speciale formula, ottenuta da sfridi di lavorazione della carta kraft uniti alle fibre dei ritagli di lavorazione della pura cellulosa, crea una gamma di prodotti dal colore sabbia e gradevole all’olfatto dell’utilizzatore finale. E-Tissue grazie alle sue straordinarie caratteristiche garantisce al prodotto un’elevata capacità di assorbenza, morbidezza al tatto, elevata resistenza. Una linea adatta a tutti gli ambienti con performance elevate e equiparabili alla pura cellulosa. COLORE BEIGE MATERIA PRIMA E-TISSUE NR. VELI 3 NR. STRAPPI 500 ALTEZZA FORMATO (CM) 26,50 LUNGHEZZA FORMATO (CM) 34,00 LUNGHEZZA ROTOLO (M) 170,00 DIAMETRO ROTOLO (CM) 28,00 DIAMETRO FORO ANIMA (MM) 72 CONFEZIONI PER COLLO 2 BANCALIZZAZIONE 54', '9b98ba2f-3efe-4085-9247-67487c5d8325', '21ea40d5-5c38-4332-a86c-10390ac3da6e', '14.50', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/i0xa5l8m8mk.png', 'true', '1'),
  ('fe845dfd-db2a-4657-ac1d-e7796789c466', 'COLTELLO BIANCO FLEXY RIUTILIZZABILI E LAVABILI - 50 PZ.', '', '4c48251c-2ba8-4822-8595-a56d401085b0', '2bb3d016-7d38-483b-be0c-cb57f27c10d8', '2.20', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/77k4bx9nl23.jpg', 'true', '1'),
  ('ff859425-4e49-4d44-85c6-cd45f7e66877', 'SACCHI CALCINACCI RIS. EDILE 45x70 AMBRA -  [PREZZO CARTONE AL KG]', 'Sacchi calcinacci ris. edile 45x70 Ambra', '9b98ba2f-3efe-4085-9247-67487c5d8325', '5e8726b1-1209-467c-96ca-a7461c1b44ca', '1.90', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/28f0z9pz78c.png', 'true', '1'),
  ('ff956d47-6ba4-487e-a458-3ccb55364a80', 'CARTA IGIENICA MINI JUMBO 1x12 100% CELLULOSA', 'Carta igienica mini jumbo 1X12 100% cellulosa', '9b98ba2f-3efe-4085-9247-67487c5d8325', '21ea40d5-5c38-4332-a86c-10390ac3da6e', '22.95', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/68xycyr8zgt.png', 'true', '1'),
  ('ff9e2284-d4df-47bb-a7d5-44af7bb61635', 'CARTA SALVAFRESCHEZZA TERMOSALDABILE - MISURA 30x40 (INTERNO ALLUMINIATO)', '', '4c48251c-2ba8-4822-8595-a56d401085b0', '19ae6e60-0d77-4df5-9110-64dbbfa40b65', '12.60', 'https://xwblrtstxlsxtxmrvxxk.supabase.co/storage/v1/object/public/products/product-images/cuxruaace5s.jpg', 'true', '1')
) as v(id, name, description, category_id, subcategory_id, price, image_url, active, min_qty)
on conflict (id) do nothing;

commit;

-- CONTROLLO: categorie, sottocategorie e prodotti trasferiti
select c.name as categoria,
       (select count(*) from public.subcategories s where s.category_id = c.id) as sottocategorie,
       (select count(*) from public.products p where p.category_id = c.id) as prodotti
from public.categories c
where c.id in ('4c48251c-2ba8-4822-8595-a56d401085b0', '88a99207-fa2d-49cd-a978-bb4433abdcef', '9b98ba2f-3efe-4085-9247-67487c5d8325', '9e391273-29b8-4375-ae53-a2603df3d379')
order by c.sort_order;
